void process_tile_lcs(...) {
#pragma HLS DATAFLOW
    tile_buf_t stage_buf;
    load_tile(A, b, stage_buf, tile_i);
    compute_tile(stage_buf, tile_i);
    store_tile(stage_buf, A, y, tile_i);
}

for (int tile = 0; tile < NUM_TILES; tile++) {
    process_tile_lcs(A, b, y, tile * TILE_SIZE);
}

// BAD: two readers on local_A and local_tmp
#pragma HLS DATAFLOW
compute_tmp(..., local_A, local_tmp);
compute_y(..., local_A, local_tmp);   // local_A reader 2, local_tmp reader 2
store_tmp(..., local_tmp);

// GOOD: fused compute, parallel load/store
#pragma HLS DATAFLOW
load_A_task(...); load_x_task(...);
compute_fused_task(local_A, local_x, local_tmp, local_y);  // both matvecs inside
store_y_task(...); store_tmp_task(...);

// BAD: local_A_out read by two compute tasks
#pragma HLS DATAFLOW
compute_A_task(..., local_A_out);
compute_x_task(local_A_out, ...);  // reader 1
compute_w_task(local_A_out, ...);  // reader 2 — HLS 200-779

// GOOD: merge consumers
#pragma HLS DATAFLOW
compute_A_task(..., local_A_out);
compute_xw_task(local_A_out, local_x, local_w, ...);  // both uses inside one task
store_x_task(...); store_w_task(...);

// BAD: one writer, two readers on local_tmp
#pragma HLS DATAFLOW
compute_tmp(..., local_tmp);
compute_next(..., local_tmp);  // reader 1
store_tmp(..., local_tmp);     // reader 2 — HLS 200-779

// GOOD: linear chain or stream fan-out
hls::stream<tile_t, DEPTH> q;
compute_tmp(..., q);
compute_next(q, local_out);
store_tmp(..., local_out);

#pragma HLS ARRAY_PARTITION variable=local_A cyclic factor=UF dim=2
#pragma HLS DATAFLOW
load_A_task(...);   // gmem0
load_B_task(...);   // gmem1 — parallel with load_A
compute_tile_task(...);
store_C_task(...);

// inside compute:
for (int j = 0; j < N; j += UF) {
#pragma HLS PIPELINE II=1
    for (int k = 0; k < UF; k++) {
#pragma HLS UNROLL
        acc += local_A[i][j+k] * local_B[j+k][l];
    }
}

#pragma HLS DATAFLOW
load_stage(in, load_to_compute);
compute_stage(load_to_compute, compute_to_store);
store_stage(compute_to_store, out);

for (int t = 0; t < NUM_TILES + 2; ++t) {
    if (t < NUM_TILES) load_tile(..., t);
    if (t > 0 && t <= NUM_TILES) compute_tile(..., t - 1);
    if (t > 1) store_tile(..., t - 2);
}

#pragma HLS DATAFLOW
 for (int t = 0; t < NUM_TILES + 2; ++t) {
    if (t < NUM_TILES) load_tile(in, in_buf[t & 1], t);
    if (t > 0 && t <= NUM_TILES) compute_tile(in_buf[(t - 1) & 1], out_buf[(t - 1) & 1], t - 1);
    if (t > 1) store_tile(out_buf[(t - 2) & 1], out, t - 2);
}

data_t buf0[TILE];
data_t buf1[TILE];
data_t* load_buf  = (t & 1) ? buf1 : buf0;
data_t* compute_buf = (t & 1) ? buf0 : buf1;

// BAD: tile loops inside DATAFLOW reload A each tile
#pragma HLS DATAFLOW
for (i0 = 0; i0 < N; i0 += TILE) {
    load_tile_A(A, local_A, i0);  // HLS 200-1013
    compute_tile(...);
}

// GOOD: fused dual-layout load, phased compute on locals
#pragma HLS DATAFLOW
fused_load_task(y1, y2, A, local_y1, local_y2, local_A_row, local_A_col);
phase1_task(local_x1, local_A_row, local_y1);
phase2_task(local_x2, local_A_col, local_y2);
fused_store_task(x1, x2, local_x1, local_x2);

#pragma HLS DATAFLOW
for (int t = 0; t < NUM_TILES + 1; ++t) {
    if (t < NUM_TILES) load_tile(in, tile_buf[t & 1], t);
    if (t > 0) compute_tile(tile_buf[(t - 1) & 1], out, t - 1);
}

#pragma HLS DATAFLOW
hls::stream<data_t> s1, s2;
#pragma HLS STREAM variable=s1 depth=64
#pragma HLS STREAM variable=s2 depth=64
producer(in, s1, n);
compute(s1, s2, n);
consumer(s2, out, n);

#pragma HLS DATAFLOW
load_stage(in, local_or_stream, n);
compute_stage(local_or_stream, out_local_or_stream, n);
store_stage(out_local_or_stream, out, n);

// load/store stages should be pipelined, burst-friendly, and bounded by tile/chunk size.

data_t old_buf[TILE];
data_t new_buf[TILE];

compute: for (int i = 0; i < TILE; ++i) {
#pragma HLS PIPELINE II=1
    new_buf[i] = update_from_old(old_buf, i);
}

// After the step: swap old_buf/new_buf or copy new_buf back as required.

#pragma HLS DATAFLOW
 for (int t = 0; t < NUM_TILES + 1; ++t) {
    if (t < NUM_TILES) load_tile(in, buf[t & 1], t);
    if (t > 0) compute_tile(buf[(t - 1) & 1], out, t - 1);
}
